+public class ChatEvals
+{
+    private static IDistributedApplicationTestingBuilder _appHostBuilder = null!;
+    private static DistributedApplication _app = null!;
+    private static IChatClient _chatClient = null!;
+    private static ReportingConfiguration _reportingConfig = null!;
+
+    [ClassInitialize]
+    public static async Task Setup(TestContext context)
+    {
+        _appHostBuilder = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
+        _app = await _appHostBuilder.BuildAsync();
+        await _app.StartAsync();
+
+        _chatClient = _app.Services.GetRequiredService<IChatClient>();
+        _reportingConfig = CreateReportingConfiguration();
+    }
+
+    [ClassCleanup]
+    public static async Task Cleanup()
+    {
+        await _app.DisposeAsync();
+    }
+
+    [TestMethod]
+    public async Task Chat_Response_Is_Relevant()
+    {
+        await using var scenario = await _reportingConfig.CreateScenarioRunAsync(
+            scenarioName: nameof(Chat_Response_Is_Relevant));
+
+        var messages = new List<ChatMessage>
+        {
+            new(ChatRole.User, "What is the capital of France?")
+        };
+
+        var response = await _chatClient.GetResponseAsync(messages);
+
+        var result = await scenario.EvaluateAsync(messages, response);
+        var relevance = result.Get<NumericMetric>(RelevanceEvaluator.RelevanceMetricName);
+
+        Assert.IsTrue(relevance.Interpretation?.Rating >= EvaluationRating.Good,
+            $"Relevance rating was {relevance.Interpretation?.Rating}");
+    }
+
+    [TestMethod]
+    public async Task Chat_Response_Is_Coherent()
+    {
+        await using var scenario = await _reportingConfig.CreateScenarioRunAsync(
+            scenarioName: nameof(Chat_Response_Is_Coherent));
+
+        var messages = new List<ChatMessage>
+        {
+            new(ChatRole.User, "Explain how photosynthesis works in simple terms.")
+        };
+
+        var response = await _chatClient.GetResponseAsync(messages);
+
+        var result = await scenario.EvaluateAsync(messages, response);
+        var coherence = result.Get<NumericMetric>(CoherenceEvaluator.CoherenceMetricName);
+
+        Assert.IsTrue(coherence.Interpretation?.Rating >= EvaluationRating.Good,
+            $"Coherence rating was {coherence.Interpretation?.Rating}");
+    }
+
+    private static ReportingConfiguration CreateReportingConfiguration()
+    {
+        var evaluators = new IEvaluator[]
+        {
+            new RelevanceEvaluator(),
+            new CoherenceEvaluator(),
+            new FluencyEvaluator(),
+            new GroundednessEvaluator(),
+        };
+
+        return DiskBasedReportingConfiguration.Create(
+            storageRootPath: Path.Combine(Directory.GetCurrentDirectory(), "eval-reports"),
+            evaluators: evaluators,
+            chatConfiguration: new ChatConfiguration(_chatClient));
+    }
+}
